/* fotos alojadas en el repositorio: grande (1000 px) y miniatura (480 px) en la subcarpeta sm/ */
const IMG_DEP=id=>"img/deportes/"+id+".webp";
const smallOf=u=>/^img\/(deportes|hogar)\/[^/]+$/.test(u||"")?u.replace(/\/([^/]+)$/,"/sm/$1"):u;
/* identificador estable de cada producto base (no cambia aunque se edite el nombre o la referencia) */
const slugId=s=>String(s).normalize("NFD").replace(/[̀-ͯ]/g,"").toLowerCase().replace(/[^a-z0-9]+/g,"-").replace(/^-|-$/g,"");
function baseInfo(p){if(!p.t&&INFO[p.r])Object.assign(p,INFO[p.r]);p.fam=p.fam||p.n;if(p.t)p.n=p.t;if(!p.id)p.id="b-"+slugId(p.r||p.fam);p.k=p.k||[];p.x=p.x||[];
 if(p.c==="jugueteria")p.c="deportes";deriveEmb(p);return p}
/* dos catálogos: Deportes (incluye la línea de juguetería) y Hogar */
const TOYS=["Montables","Carpas y túneles","Arte y manualidades"];
/* embalaje en que se vende cada referencia: tipo, cantidad por embalaje y contenido */
const EMB_TIPOS=["Caja","Bulto","Paca","Set","Juego","Docena","Blíster","Unidad"];
const EMB_PL={Caja:"cajas",Bulto:"bultos",Paca:"pacas",Set:"sets",Juego:"juegos",Docena:"docenas","Blíster":"blísteres",Unidad:"unidades"};
function deriveEmb(p){if(p.emb)return p;const pr=((p.x||[]).find(([l])=>/^Presentaci/i.test(l))||[])[1]||"";
 const m=pr.match(/\b(caja|bulto|paca)\s*x\s*(\d+)\s*([a-záéíóúñ]+)?/i)||pr.match(/\b(set|juego)\s*x\s*(\d+)\s*([a-záéíóúñ]+)?/i);
 const unit=w=>/^(sets?|pares|juegos|docenas)$/i.test(w||"")?w.toLowerCase():"unidades";
 if(m){p.emb=m[1][0].toUpperCase()+m[1].slice(1).toLowerCase();p.embq=`${m[2]} ${unit(m[3])}`}
 else{const w=pr.match(/^\s*(set|juego|unidad)\b/i);p.emb=w?w[1][0].toUpperCase()+w[1].slice(1).toLowerCase():"Caja";p.embq=""}
 if(p.cont===undefined)p.cont=pr;return p}
/* cambios hechos desde el panel (data/cambios.json): {id:{n,r,c,s,d,k,x,ag,u,oculto}} */
const EDITABLE=["n","r","c","s","d","k","x","emb","embq","cont","op","vr","pk"];
function applyChange(p,ch){if(!ch)return p;EDITABLE.forEach(f=>{if(ch[f]!==undefined)p[f]=ch[f]});if("ag" in ch)p.ag=ch.ag?1:0;
 if(ch.u){p.u=ch.u;p.g=null;p.real=1}if(ch.oculto)p.oculto=1;p.editado=1;return p}
